{"path": "tests/test_setup.py", "content": "import ast
from pathlib import Path


def _get_install_requires():
    """Parse setup.py and return the install_requires list."""
    setup_py = Path(__file__).parent.parent / "setup.py"
    tree = ast.parse(setup_py.read_text())
    for node in ast.walk(tree):
        if isinstance(node, ast.Call) and getattr(node.func, "id", None) == "setup":
            for kw in node.keywords:
                if kw.arg == "install_requires":
                    return ast.literal_eval(kw.value)
    raise AssertionError("install_requires not found in setup.py")


def test_packaging_requirement_has_minimum_version():
    """The packaging dependency must require packaging>=17.0 for Version.release."""
    install_requires = _get_install_requires()
    packaging_req = next(req for req in install_requires if req.startswith("packaging"))
    assert packaging_req == "packaging>=17.0""}

